    let mut positions = Vec::new();
    let mut chars = mask.chars();

    while let Some(c) = chars.next() {
        if c == '?' {
            match chars.next() {
                Some('?') => positions.push(vec!['?']),
                Some(token @ '1'..='4') => {
                    let idx = (token as usize) - ('1' as usize);
                    match &custom_charsets[idx] {
                        Some(charset) => positions.push(charset.clone()),
                        None => {
