        let mask = parse_mask("abc", &NO_CUSTOM).unwrap();
        assert_eq!(mask.positions.len(), 3);
        assert_eq!(mask.positions[0], vec!['a']);
        assert_eq!(mask.positions[1], vec!['b']);
        assert_eq!(mask.positions[2], vec!['c']);
