        "stdout": "struct MaskPasswordGenerator {
    positions: Vec<Vec<u8>>,
    indices: Vec<usize>,
    total: usize,
    generated: usize,
    finished: bool,
}

impl MaskPasswordGenerator {
    fn new(mask: ParsedMask) -> Self {
        let total = mask_password_count(&mask);
        let len = mask.positions.len();
        // Convert char positions to u8 once at construction
        let positions = mask
            .positions
            .into_iter()
            .map(|chars| chars.into_iter().map(|c| c as u8).collect())
            .collect();
        Self {
            positions,
            indices: vec![0; len],
            total,
            generated: 0,
            finished: total == 0,
        }
    }

    fn current_password(&self) -> Vec<u8> {
        self.indices
            .iter()
            .enumerate()
            .map(|(pos, &idx)| self.positions[pos][idx])
            .collect()
    }
}

impl Iterator for MaskPasswordGenerator {
    type Item = Vec<u8>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.finished {
            return None;
        }

        let password = self.current_password();
        self.generated += 1;

        if self.generated == self.total {
            self.finished = true;
        } else {
            // Increment: rightmost position first (odometer style)
            let mut carry = true;
            for i in (0..self.indices.len()).rev() {
                if carry {
                    self.indices[i] += 1;
                    if self.indices[i] >= self.positions[i].len() {
                        self.indices[i] = 0;
                    } else {
                        carry = false;
                    }
                }
            }
        }

        Some(password)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.total - self.generated;
        (remaining, Some(remaining))
    }
}

pub fn mask_password_iter(mask: ParsedMask) -> impl Iterator<Item = Vec<u8>> {
    MaskPasswordGenerator::new(mask)
}

