    let mut custom_charsets: CustomCharsets = [None, None, None, None];
    for (i, name) in custom_charset_names.iter().enumerate() {
        let value: Option<&String> = matches.try_get_one(name)?;
        if let Some(definition) = value {
            if mask.is_none() {
